-- P0 fictional patient runtime. This deliberately stays separate from production clinical tables.
alter table public.demo_patients add column if not exists tester_id uuid, add column if not exists phone text not null default '', add column if not exists email text not null default '', add column if not exists chief_complaint text not null default '', add column if not exists status text not null default 'active', add column if not exists updated_at timestamptz not null default now();
create index if not exists demo_patients_tester_idx on public.demo_patients(tester_id,created_at desc);
create table if not exists public.demo_patient_history(patient_id uuid primary key references public.demo_patients(id) on delete cascade,tester_id uuid not null,psychiatric_history text not null default '',medical_history text not null default '',previous_treatments text not null default '',hospitalizations text not null default '',family_history text not null default '',substance_history text not null default '',social_functioning text not null default '',allergies text not null default '',updated_at timestamptz not null default now());
create table if not exists public.demo_sessions(id uuid primary key default gen_random_uuid(),tester_id uuid not null,patient_id uuid not null references public.demo_patients(id) on delete cascade,session_type text not null check(session_type in ('initial_assessment','follow_up')),status text not null default 'draft' check(status in ('draft','completed')),version integer not null default 1,started_at timestamptz not null default now(),completed_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),check((status='completed')=(completed_at is not null)));
create unique index if not exists demo_one_draft_session on public.demo_sessions(patient_id) where status='draft'; create index if not exists demo_sessions_patient_idx on public.demo_sessions(tester_id,patient_id,created_at desc);
create table if not exists public.demo_session_sections(id uuid primary key default gen_random_uuid(),tester_id uuid not null,patient_id uuid not null references public.demo_patients(id) on delete cascade,session_id uuid not null references public.demo_sessions(id) on delete cascade,section_key text not null check(section_key in ('interview','functioning','adherence','effects','mse','assessment','plan','review')),content text not null default '',source text not null default 'manual' check(source in ('manual','dictation','ai_proposal')),version integer not null default 1,updated_at timestamptz not null default now(),unique(session_id,section_key));
create table if not exists public.demo_risk_assessments(session_id uuid primary key references public.demo_sessions(id) on delete cascade,tester_id uuid not null,patient_id uuid not null references public.demo_patients(id) on delete cascade,suicidal_ideation text not null default 'not_assessed' check(suicidal_ideation in ('not_assessed','unknown','negative','positive')),intent text not null default 'not_assessed' check(intent in ('not_assessed','unknown','negative','positive')),plan text not null default 'not_assessed' check(plan in ('not_assessed','unknown','negative','positive')),self_harm text not null default 'not_assessed' check(self_harm in ('not_assessed','unknown','negative','positive')),attempt_history text not null default 'not_assessed' check(attempt_history in ('not_assessed','unknown','negative','positive')),protective_factors text not null default '',clinical_note text not null default '',version integer not null default 1,updated_at timestamptz not null default now());
create table if not exists public.demo_medications(id uuid primary key default gen_random_uuid(),tester_id uuid not null,patient_id uuid not null references public.demo_patients(id) on delete cascade,medication_name text not null,dose numeric not null check(dose>0),unit text not null,frequency text not null,effective_from date not null default current_date,started_at date not null default current_date,ended_at date,status text not null default 'active' check(status in ('active','stopped')),notes text not null default '',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create index if not exists demo_medications_patient_idx on public.demo_medications(tester_id,patient_id,status);
create table if not exists public.demo_medication_events(id uuid primary key default gen_random_uuid(),tester_id uuid not null,patient_id uuid not null references public.demo_patients(id) on delete cascade,medication_id uuid not null references public.demo_medications(id) on delete cascade,session_id uuid references public.demo_sessions(id) on delete set null,event_type text not null check(event_type in ('started','changed','stopped')),previous_state jsonb,new_state jsonb not null,reason text not null default '',effective_on date not null default current_date,created_at timestamptz not null default now());

do $$ declare t text; begin foreach t in array array['demo_patient_history','demo_sessions','demo_session_sections','demo_risk_assessments','demo_medications','demo_medication_events'] loop execute format('alter table public.%I enable row level security',t); execute format('drop policy if exists demo_read on public.%I',t); execute format('create policy demo_read on public.%I for select using (true)',t); execute format('grant select on table public.%I to anon,authenticated',t); end loop; end $$;

create or replace function public.demo_tester_bootstrap(p_tester uuid) returns void language plpgsql security definer set search_path=public as $$
declare maria uuid:=md5(p_tester::text||':maria')::uuid; giannis uuid:=md5(p_tester::text||':giannis')::uuid; eleni uuid:=md5(p_tester::text||':eleni')::uuid; kostas uuid:=md5(p_tester::text||':kostas')::uuid; begin
 if p_tester is null then raise exception 'tester_required'; end if;
 insert into public.demo_patients(id,tester_id,first_name,last_name,reported_age,note,chief_complaint) values
 (maria,p_tester,'Μαρία','',32,'Μείζον καταθλιπτικό επεισόδιο · Διαταραχή πανικού','Παρακολούθηση διάθεσης, άγχους και ανοχής αγωγής.'),(giannis,p_tester,'Γιάννης','Π.',41,'Αγχώδης διαταραχή','Παρακολούθηση άγχους.'),(eleni,p_tester,'Ελένη','Δ.',28,'Παρακολούθηση αγωγής','Παρακολούθηση αποτελεσματικότητας και ανεπιθύμητων ενεργειών.'),(kostas,p_tester,'Κώστας','Σ.',37,'Νέα αρχική αξιολόγηση','Επίμονο άγχος και δυσκολία ύπνου περίπου 4 μήνες.') on conflict(id) do nothing;
 insert into public.demo_patient_history(patient_id,tester_id,psychiatric_history,medical_history,previous_treatments,family_history,substance_history,social_functioning) values(maria,p_tester,'Καταθλιπτικά και αγχώδη συμπτώματα με κρίσεις πανικού.','Δεν έχει καταγραφεί σημαντικό σωματικό ιστορικό.','Brief therapy στην ηλικία των 26.','Μητέρα με ιστορικό κατάθλιψης.','Αλκοόλ 1–2 φορές/εβδομάδα. Δεν αναφέρονται άλλες ουσίες.','Επέστρεψε σε πλήρες ωράριο εργασίας.') on conflict(patient_id) do nothing;
 if not exists(select 1 from public.demo_medications where patient_id=maria and medication_name='Sertraline') then insert into public.demo_medications(tester_id,patient_id,medication_name,dose,unit,frequency,effective_from,started_at,notes) values(p_tester,maria,'Sertraline',100,'mg','1× πρωί','2026-09-03','2026-06-06','Μειωμένη libido υπό παρακολούθηση'); end if;
end $$;
create or replace function public.demo_patient_create_v2(p_tester uuid,p_first_name text,p_last_name text default '',p_age integer default null,p_phone text default '',p_email text default '',p_complaint text default '') returns public.demo_patients language plpgsql security definer set search_path=public as $$ declare r public.demo_patients; begin if p_tester is null or length(trim(coalesce(p_first_name,'')))<1 then raise exception 'invalid_patient'; end if; insert into public.demo_patients(tester_id,first_name,last_name,reported_age,phone,email,note,chief_complaint) values(p_tester,trim(p_first_name),trim(coalesce(p_last_name,'')),p_age,trim(coalesce(p_phone,'')),trim(coalesce(p_email,'')),trim(coalesce(p_complaint,'')),trim(coalesce(p_complaint,''))) returning * into r; insert into public.demo_patient_history(patient_id,tester_id) values(r.id,p_tester); return r; end $$;
create or replace function public.demo_session_start(p_tester uuid,p_patient uuid,p_type text) returns public.demo_sessions language plpgsql security definer set search_path=public as $$ declare r public.demo_sessions; begin if p_type not in ('initial_assessment','follow_up') then raise exception 'invalid_session_type'; end if; if not exists(select 1 from public.demo_patients where id=p_patient and tester_id=p_tester) then raise exception 'patient_not_found'; end if; select * into r from public.demo_sessions where patient_id=p_patient and tester_id=p_tester and status='draft' order by created_at desc limit 1; if r.id is null then insert into public.demo_sessions(tester_id,patient_id,session_type) values(p_tester,p_patient,p_type) returning * into r; end if; return r; end $$;
create or replace function public.demo_session_save_section(p_tester uuid,p_session uuid,p_section text,p_content text,p_source text default 'manual',p_expected_version integer default null) returns public.demo_session_sections language plpgsql security definer set search_path=public as $$ declare s public.demo_sessions; r public.demo_session_sections; begin select * into s from public.demo_sessions where id=p_session and tester_id=p_tester for update; if s.id is null or s.status<>'draft' then raise exception 'session_unavailable'; end if; if p_section not in ('interview','functioning','adherence','effects','mse','assessment','plan','review') then raise exception 'invalid_section'; end if; select * into r from public.demo_session_sections where session_id=p_session and section_key=p_section for update; if r.id is null then insert into public.demo_session_sections(tester_id,patient_id,session_id,section_key,content,source) values(p_tester,s.patient_id,p_session,p_section,coalesce(p_content,''),p_source) returning * into r; else if p_expected_version is not null and r.version<>p_expected_version then raise exception 'stale_section'; end if; update public.demo_session_sections set content=coalesce(p_content,''),source=p_source,version=version+1,updated_at=now() where id=r.id returning * into r; end if; update public.demo_sessions set version=version+1,updated_at=now() where id=p_session; return r; end $$;
create or replace function public.demo_session_save_risk(p_tester uuid,p_session uuid,p_risk jsonb,p_expected_version integer default null) returns public.demo_risk_assessments language plpgsql security definer set search_path=public as $$ declare s public.demo_sessions; r public.demo_risk_assessments; begin select * into s from public.demo_sessions where id=p_session and tester_id=p_tester for update; if s.id is null or s.status<>'draft' then raise exception 'session_unavailable'; end if; select * into r from public.demo_risk_assessments where session_id=p_session for update; if r.session_id is not null and p_expected_version is not null and r.version<>p_expected_version then raise exception 'stale_risk'; end if; insert into public.demo_risk_assessments(session_id,tester_id,patient_id,suicidal_ideation,intent,plan,self_harm,attempt_history,protective_factors,clinical_note) values(p_session,p_tester,s.patient_id,coalesce(p_risk->>'suicidal_ideation','not_assessed'),coalesce(p_risk->>'intent','not_assessed'),coalesce(p_risk->>'plan','not_assessed'),coalesce(p_risk->>'self_harm','not_assessed'),coalesce(p_risk->>'attempt_history','not_assessed'),coalesce(p_risk->>'protective_factors',''),coalesce(p_risk->>'clinical_note','')) on conflict(session_id) do update set suicidal_ideation=excluded.suicidal_ideation,intent=excluded.intent,plan=excluded.plan,self_harm=excluded.self_harm,attempt_history=excluded.attempt_history,protective_factors=excluded.protective_factors,clinical_note=excluded.clinical_note,version=demo_risk_assessments.version+1,updated_at=now() returning * into r; update public.demo_sessions set version=version+1,updated_at=now() where id=p_session; return r; end $$;
create or replace function public.demo_session_finalize(p_tester uuid,p_session uuid,p_expected_version integer) returns public.demo_sessions language plpgsql security definer set search_path=public as $$ declare s public.demo_sessions; missing text; begin select * into s from public.demo_sessions where id=p_session and tester_id=p_tester for update; if s.id is null or s.status<>'draft' then raise exception 'session_unavailable'; end if; if p_expected_version is null or s.version<>p_expected_version then raise exception 'stale_session'; end if; select string_agg(u.section,', ') into missing from unnest(array['interview','mse','assessment','plan','review']) as u(section) where not exists(select 1 from public.demo_session_sections where session_id=p_session and section_key=u.section and length(trim(content))>0); if missing is not null then raise exception 'missing_sections:%',missing; end if; if not exists(select 1 from public.demo_risk_assessments where session_id=p_session and suicidal_ideation<>'not_assessed') then raise exception 'risk_required'; end if; update public.demo_sessions set status='completed',completed_at=now(),version=version+1,updated_at=now() where id=p_session returning * into s; return s; end $$;
create or replace function public.demo_medication_start(p_tester uuid,p_patient uuid,p_session uuid,p_name text,p_dose numeric,p_unit text,p_frequency text,p_effective date,p_reason text default '') returns public.demo_medications language plpgsql security definer set search_path=public as $$ declare r public.demo_medications; begin if not exists(select 1 from public.demo_patients where id=p_patient and tester_id=p_tester) then raise exception 'patient_not_found'; end if; insert into public.demo_medications(tester_id,patient_id,medication_name,dose,unit,frequency,effective_from,started_at,notes) values(p_tester,p_patient,trim(p_name),p_dose,trim(p_unit),trim(p_frequency),p_effective,p_effective,trim(coalesce(p_reason,''))) returning * into r; insert into public.demo_medication_events(tester_id,patient_id,medication_id,session_id,event_type,new_state,reason,effective_on) values(p_tester,p_patient,r.id,p_session,'started',jsonb_build_object('dose',r.dose,'unit',r.unit,'frequency',r.frequency,'status',r.status),trim(coalesce(p_reason,'')),p_effective); return r; end $$;
create or replace function public.demo_medication_change(p_tester uuid,p_medication uuid,p_session uuid,p_dose numeric,p_unit text,p_frequency text,p_effective date,p_reason text default '') returns public.demo_medications language plpgsql security definer set search_path=public as $$ declare r public.demo_medications; prev jsonb; begin select * into r from public.demo_medications where id=p_medication and tester_id=p_tester for update; if r.id is null or r.status<>'active' then raise exception 'medication_not_found'; end if; prev:=jsonb_build_object('dose',r.dose,'unit',r.unit,'frequency',r.frequency,'status',r.status); update public.demo_medications set dose=p_dose,unit=trim(p_unit),frequency=trim(p_frequency),effective_from=p_effective,updated_at=now() where id=p_medication returning * into r; insert into public.demo_medication_events(tester_id,patient_id,medication_id,session_id,event_type,previous_state,new_state,reason,effective_on) values(p_tester,r.patient_id,r.id,p_session,'changed',prev,jsonb_build_object('dose',r.dose,'unit',r.unit,'frequency',r.frequency,'status',r.status),trim(coalesce(p_reason,'')),p_effective); return r; end $$;
grant execute on function public.demo_tester_bootstrap(uuid),public.demo_patient_create_v2(uuid,text,text,integer,text,text,text),public.demo_session_start(uuid,uuid,text),public.demo_session_save_section(uuid,uuid,text,text,text,integer),public.demo_session_save_risk(uuid,uuid,jsonb,integer),public.demo_session_finalize(uuid,uuid,integer),public.demo_medication_start(uuid,uuid,uuid,text,numeric,text,text,date,text),public.demo_medication_change(uuid,uuid,uuid,numeric,text,text,date,text) to anon,authenticated;
